mapper.select:
SELECT ROOM_ID, USER_ID, ADMIN_ID, STATUS, CREATED_AT, CLOSED_AT
FROM CHAT_ROOMS
WHERE ROOM_ID = #{roomId}

mapper.update:
UPDATE CHAT_MESSAGES
SET IS_READ = TRUE
WHERE ROOM_ID = #{roomId}
  AND SENDER_ID != #{readerId}
  AND IS_READ = FALSE

mapper.select:
SELECT COUNT(*)
FROM CHAT_MESSAGES
WHERE ROOM_ID = #{roomId}
  AND SENDER_ID != #{readerId}
  AND IS_READ = FALSE
